import CarViewer from './viewer/ViewerLoader';
import { useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowLeft, ArrowRight, Camera, Check, CheckCircle2, ChevronLeft, ChevronRight, CircleHelp, Download, Eye, FileImage, Grid2X2, ImagePlus, Layers3, LoaderCircle, LockKeyhole, Menu, MoreHorizontal, Plus, RotateCcw, ScanLine, ShieldCheck, Trash2, Upload, X } from 'lucide-react';
import { CONFIG, EMPTY_DETAILS, photoKey, slots, title, type CaptureSlot, type CarDetails, type FrameCount, type OriginalPhoto, type Project } from './model';
import { canDisplay, repository, storageError } from './storage';
import { api, cloudEnabled, loadPrivateImage, supabase } from './backend';
